const IMPORTED_LABEL_COLOR = "#94a3b8";

export type ImportedIssueRow = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Distinct label names; missing ones are created by the write. */
  readonly labelNames: readonly string[];
};

export type IssueImportWrite = {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedIssueRow[];
};

export type IssueImportBatch = {
  readonly replayed: boolean;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

/** The import already on file for this key in this workspace, if any. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportBatch | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toImportBatch(row) : null;
}

/**
 * Writes a whole import in one synchronous transaction: numbering, new labels,
 * issues, label joins and the key record either all land or none do. A key
 * already on file writes nothing and returns the first import's ids.
 */
export function writeIssueImport(input: IssueImportWrite): IssueImportBatch {
  return getDb().transaction((tx) => {
    const prior = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (prior) return toImportBatch(prior);

    const stamp = toIsoTimestamp(new Date());

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = (highest?.value ?? 0) + 1;

    const names = [...new Set(input.rows.flatMap((row) => row.labelNames))];
    const labelIds = new Map<string, LabelId>();
    if (names.length > 0) {
      const existing = tx
        .select()
        .from(labels)
        .where(
          and(orgPredicate(labels.orgId, input.orgId), inArray(labels.name, names)),
        )
        .all();
      for (const label of existing) labelIds.set(label.name, label.id as LabelId);
    }
    for (const name of names) {
      if (labelIds.has(name)) continue;
      const labelId = newId() as LabelId;
      tx.insert(labels)
        .values({
          id: labelId,
          orgId: input.orgId,
          name,
          color: IMPORTED_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIds.set(name, labelId);
    }

    const issueIds: IssueId[] = [];
    for (const row of input.rows) {
      const issueId = newId() as IssueId;
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      number += 1;
      issueIds.push(issueId);

      const joins = row.labelNames.flatMap((name) => {
        const labelId = labelIds.get(name);
        return labelId ? [{ orgId: input.orgId, issueId, labelId }] : [];
      });
      if (joins.length > 0) tx.insert(issueLabels).values(joins).run();
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, projectId: input.projectId, issueIds };
  });
}

function toImportBatch(row: {
  projectId: string;
  issueIds: string;
}): IssueImportBatch {
  return {
    replayed: true,
    projectId: row.projectId as ProjectId,
    issueIds: JSON.parse(row.issueIds) as IssueId[],
  };
}

