    let number = (highest?.value ?? 0) + 1;

    const names = [...new Set(input.rows.flatMap((row) => row.labelNames))];
    const labelIds = new Map<string, LabelId>();
    if (names.length > 0) {
      const existing = tx
        .select()
        .from(labels)
        .where(
          and(orgPredicate(labels.orgId, input.orgId), inArray(labels.name, names)),
        )
        .all();
      for (const label of existing) labelIds.set(label.name, label.id as LabelId);
    }
    for (const name of names) {
      if (labelIds.has(name)) continue;
      const labelId = newId() as LabelId;
      tx.insert(labels)
        .values({
          id: labelId,
          orgId: input.orgId,
          name,
          color: IMPORTED_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIds.set(name, labelId);
    }

    const issueIds: IssueId[] = [];
    for (const row of input.rows) {
      const issueId = newId() as IssueId;
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      number += 1;
      issueIds.push(issueId);

      const joins = row.labelNames.flatMap((name) => {
        const labelId = labelIds.get(name);
        return labelId ? [{ orgId: input.orgId, issueId, labelId }] : [];
      });
      if (joins.length > 0) tx.insert(issueLabels).values(joins).run();
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, projectId: input.projectId, issueIds };
  });
}

