/** Rate bucket shared with single-issue creation; the import spends one unit per row. */
const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Bulk import of parsed rows into one project, in file order. The gates are
 * `createIssue`'s, with the plan quota applied to the whole batch. A key already
 * on file is a replay: the first import's issues come back and nothing is
 * written. Nothing is written until the quota and rate allowance both pass, and
 * only one `issues.imported` event is published for the batch — no per-row
 * `issue.created`, so nobody is notified and no webhook fires.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  const prior = await issueRepo.findIssueImport(input.orgId, input.importKey);
  if (prior) return loadImportResult(input.orgId, prior);

  assertNotArchived("Project", project.id, project);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const emails = [
    ...new Set(input.rows.flatMap((row) => (row.assigneeEmail ? [row.assigneeEmail] : []))),
  ];
  const assignees = await memberRepo.findActiveUserIdsByEmail(input.orgId, emails);

  const batch = issueRepo.writeIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail) ?? null),
      dueAt: row.dueAt,
      labelNames: [...new Set(row.labels)],
    })),
  });

  if (batch.replayed) return loadImportResult(input.orgId, batch);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: batch.projectId,
    importKey: input.importKey,
    issueIds: batch.issueIds,
  });

  return loadImportResult(input.orgId, batch);
}

